# Reorganiza a pasta 04-prototipo no padrão de pastas do professor, usando os arquivos originais do repositório.
# Rode na raiz do repositório: powershell -ExecutionPolicy Bypass -File .\reorganizar-wireframes.ps1
git rev-parse --show-toplevel | Out-Null
if ($LASTEXITCODE -ne 0) { Write-Host "Rode este script na raiz do repositório."; exit 1 }
$P = "milestone_3/docs/04-prototipo"
$W = "milestone_3/docs/04-prototipo/wireframes"

# 1. Conteúdo antigo do professor: copia os originais do repositório para "conteudo antigo"
$tmp = "$P/conteudo antigo/_tmp"
New-Item -ItemType Directory -Force -Path $tmp | Out-Null
$antigos = @("$W/pub", "$W/cidadao", "$W/operador", "$W/admin-instituicao", "$W/admin-plataforma")
git --work-tree="$tmp" checkout HEAD -- $antigos
# site-map.svg2 pode ter sido apagado em um commit anterior: recupera a última versão existente
$c = git rev-list -n 1 HEAD -- "$P/site-map.svg2"
if ($c) { git --work-tree="$tmp" checkout "$c~1" -- "$P/site-map.svg2" 2>$null; if ($LASTEXITCODE -ne 0) { git --work-tree="$tmp" checkout HEAD -- "$P/site-map.svg2" } ; git reset -q -- "$P/site-map.svg2" }
New-Item -ItemType Directory -Force -Path "$P/conteudo antigo/wireframes" | Out-Null
Copy-Item -Recurse -Force "$tmp/$W/*" "$P/conteudo antigo/wireframes/"
if (Test-Path "$tmp/$P/site-map.svg2") { Copy-Item -Force "$tmp/$P/site-map.svg2" "$P/conteudo antigo/site-map.svg2" }
Remove-Item -Recurse -Force $tmp
git rm -r -q --cached --ignore-unmatch -- $antigos "$P/site-map.svg2"
foreach ($f in @("01-pagina-inicial.svg","02-login.svg","03-cadastro.svg")) { if (Test-Path "$W/pub/$f") { Remove-Item -Force "$W/pub/$f" } }
foreach ($d in @("cidadao","operador","admin-instituicao","admin-plataforma")) { if (Test-Path "$W/$d") { Remove-Item -Recurse -Force "$W/$d" } }

# 2. Remove as pastas por área criadas antes (cópias com metadados extras)
foreach ($d in @("01-login","02-painel","03-orcamento","04-ordens-de-servico","05-clientes","06-veiculos","07-pecas-estoque","08-agenda-boxes","09-relatorios")) { if (Test-Path "$W/$d") { Remove-Item -Recurse -Force "$W/$d" } }
foreach ($d in @("pub","secretaria","estoquista","gerente","rotulos")) { New-Item -ItemType Directory -Force -Path "$W/$d" | Out-Null }

